// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // The reference C's setL1BlockValues stores _number unchanged as `number`.
        // Buggy version stores _number + 1 instead.
        // So for the reference, after the call, number() == _number.
        // For the bug, number() == _number + 1 (unless overflow, but we don't restrict).
        // However, the assertion below will fail on the reference? No.
        // We need a rule that the reference always satisfies but the bug breaks.
        // The reference's rule: after the call, number() == _number.
        // But the user says that was already tried. Let's try a different rule:
        // The reference ensures that number is not equal to _number + 1 (unless wrap).
        // Actually, a simpler differentiating rule: the reference's number == _number.
        // If that was already tried and failed? The user says it failed because the reference broke it.
        // That would imply the reference sometimes fails that assertion, which is impossible if it stores correctly.
        // Wait: the user says the previous rule did NOT hold on reference C; the assertion already fails before any bug.
        // So we need a different rule. Let's pick: after the call, number == _number or number == _number + 1 (overflow possibility).
        // That is true for both? No, buggy always increments, so reference never equals _number+1 unless overflow.
        // Better: For the reference, number & 1 == _number & 1? No.
        // Let's think: The bug only modifies number by adding 1. So the parity of number relative to _number differs.
        // The reference makes number == _number, so parity is the same.
        // The bug makes number == _number + 1, so parity is opposite.
        // So the rule: after the call, (number & 1) == (_number & 1). This holds for reference always, but for bug it fails (since adding 1 flips parity). Unless overflow? Even with overflow, adding 1 flips the LSB regardless of wrap.
        // So this rule should work. But careful: if _number is type(uint64).max, _number + 1 overflows to 0, which has different parity? Actually, adding 1 to an odd number makes it even, and to even makes odd, always flipping the LSB. So the rule holds for reference (parity same) but fails for bug.
        // Let's assert that.
        vm.assume(_number < type(uint64).max); // avoid overflow? Actually, even with overflow, the bug still flips parity, but reference doesn't overflow. So both still differ in parity.
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
        uint64 stored = c.number();
        // Rule: stored and _number have same parity (i.e., (stored & 1) == (_number & 1))
        assertTrue((stored & 1) == (_number & 1), "Parity differs");
    }
}

